{"variables":{"queryCodes":[11,12,13,14,26,27],"filter":null,"merchantGroup":"ALL","limit":6},"query":"query ($queryCodes: [Int]!, $limit: Int, $filter: SpecialOfferMerchantListFilter, $merchantGroup: SpecialOfferTab) {
  merchantList: specialOfferMerchantList(
    queryCodes: $queryCodes
    limit: $limit
    filter: $filter
    merchantGroup: $merchantGroup
  ) {
    classification {
      queryCode
      name
      __typename
    }
    merchants {
      ...MerchantFragmentForCard
      __typename
    }
    __typename
  }
}

fragment MerchantFragmentForCard on MerchantInterface {
  merchantId
  shopId
  storeId
  name
  url
  imageUrl
  transferPageUrl
  point {
    amount
    previousAmount
    eventMessage
    bonusAmountForApp
    calculatedAmount
    __typename
  }
  displayPoints
  showPointAmount
  rewardRaised
  coupon
  opening
  redEnvelopeSettingIds
  vendorTypes
  ownedTraffic
  __typename
}"}
